    public function __construct(
        public string $name,
        public string $variant = 'outline',
    ) {}

    public function paths(): ?string
    {
        return $this->variant === 'solid'
            ? (self::SOLID[$this->name] ?? null)
            : (self::OUTLINE[$this->name] ?? null);
    }

    public function isSolid(): bool
    {
        return $this->variant === 'solid' && isset(self::SOLID[$this->name]);
    }

    /** Names available in a given variant — used by tests and the icon gallery. */
    public static function available(string $variant = 'outline'): array
    {
        return array_keys($variant === 'solid' ? self::SOLID : self::OUTLINE);
    }

    public function render(): View
    {
        return view('components.icon');
    }
}
